// Prototype (Declaration)
int calculate(int a, int b);

// Definition
int calculate(int x, int y) {
    if (x > y)
        return x - y;
    return x + y;
}

// Call by Value
int val_1 = 5;
int val_2 = 3;
int result = calculate(val_1, val_2);

int calculate(int a, int b);

// ---

void update_value(int *ptr) {
    (*ptr) *= 2;
}

// Function Call (Call by Reference)
int data = 10;
update_value(&data); // data is now 20

// ---

float power(float base, float exp);

// Function Pointer Definition
float (*operation_ptr)(float, float);

// Assignment and Invocation
operation_ptr = power;
float p = operation_ptr(2.0, 3.0); // p = 8.0

float (*operation_ptr)(float, float);
